import{_ as i,l,o as e,c as o,v as t,p as d,x as s,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"延迟型拥塞 Vegas / Swift","description":"","frontmatter":{"title":"延迟型拥塞 Vegas / Swift","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/delay-based-cc.md","filePath":"cs/delay-based-cc.md","lastUpdated":1789023840000}'),T={name:"cs/delay-based-cc.md"};function h(E,a,f,C,m,A){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="延迟型拥塞-vegas-swift" tabindex="-1">延迟型拥塞 Vegas / Swift <a class="header-anchor" href="#延迟型拥塞-vegas-swift" aria-label="Permalink to &quot;延迟型拥塞 Vegas / Swift&quot;">​</a></h1><div class="epigraph"><p>用 RTT 超过基线的量估计队列，提前减速；Vegas 在公网脆弱，Swift 把同一思想收进数据中心目标延迟。</p><footer>—— 据 Brakmo and Peterson, TCP Vegas, IEEE JSAC 1995；Kumar et al., Swift, SIGCOMM 2020 整理</footer></div><p><a href="/cs/bbr-v2-v3">BBR</a> 用 minRTT。<a href="/cs/ecn">ECN</a> 用标记。<a href="/cs/bbr-v2-v3">上一课</a> 不讲 Vegas 控制律。缺口是<strong>延迟作为主信号</strong>：Vegas 窗口规则、反向流量噪声、Swift 的 target delay。本课不把无线误码写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AIMD 等丢。Vegas：比较期望吞吐与实际，RTT 升则减窗口。公网路由变化、ACK 压缩、反向拥塞让基线漂，Vegas 常输给 Reno。数据中心 RTT 干净，Swift（及 TIMELY）用 delay 梯度或目标延迟调速，服务尾延迟，可与 ECN 双信号。与 CoDel：一个在端测 RTT，一个在箱测驻留。</p><p>不要把延迟 CC 写成「不需要 AQM」的普适解。</p><p><span class="marginnote">Vegas 1995。Swift 2020 面向 DC。本课不调每个 \\(\\alpha,\\beta\\)。</span></p><h3 id="延迟信号怕噪声" tabindex="-1">延迟信号怕噪声 <a class="header-anchor" href="#延迟信号怕噪声" aria-label="Permalink to &quot;延迟信号怕噪声&quot;">​</a></h3><p>Vegas 在公网基线漂。Swift 把目标延迟放进数据中心。卫星传播淹没队列信号。可与 ECN 组合。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：丢包 / ECN / 延迟。画：测 RTT → 相对 base → 调窗。卫星：base 已是 600 ms，队列信号淹没在传播里，延迟 CC 难。</p>',11)),(e(),d(c,null,{default:s(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%20RTT%22%5D%20--%3E%20DEL%5B%22%E8%B6%85%E9%A2%9D%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20DEL%20--%3E%20DEC%5B%22%E5%87%8F%E7%AA%97%E5%8F%A3%22%5D%0A%20%20NOISE%5B%22%E8%B7%AF%E7%94%B1%2F%E5%8F%8D%E5%90%91%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20FAIL%5B%22%E5%85%AC%E7%BD%91%20Vegas%20%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DCTCP 用 CE 比例，Swift 用 delay，都可浅队列。WFQ 隔离后延迟信号更干净。MPTCP 子流 RTT 不同，延迟信号要分路径。QUIC 可在用户态实现 Vegas 变体。</p><p>公平：延迟 CC 对短 RTT 仍可能敏，但机制与 AIMD 的 \\(1/\\mathrm{RTT}^2\\) 不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 COPA 的全部效用函数。无线上的 TCP 是下一课。后课默认：延迟信号在可控 RTT 环境有用；公网噪声大。</p><p>把 Vegas 当默认公网 CC 会吃亏。</p><p>上一课留下的缺口在本课收口；「延迟型拥塞 Vegas / Swift」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/tcp-wireless">无线上的 TCP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Vegas 用超额 RTT 调窗，公网不稳。</li><li>Swift 等把延迟 CC 放进数据中心。</li><li>与 ECN/AQM 可组合，不互相取消。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Brakmo–Peterson, 1995；Kumar et al., 2020。</li></ul>',10))])}const g=i(T,[["render",h]]);export{B as __pageData,g as default};
